-- ── The four guide drafts (content_pages) ──────────────────────────────────
INSERT INTO content_pages (id, page_key, content_type, version_no, status, title, blocks, metadata, audit_note, created_by, created_at)
VALUES ('0289b2f5-45de-4475-a5b7-24d4c596d32e', 'federal-grants-nofo-primer', 'guide', 1, 'draft', 'Federal Grants & NOFOs: A First-Timer’s Guide', $g168$[{"body": "<h1 style=\"font-size:1.875rem;font-weight:700;line-height:1.2;margin:1.5rem 0 .75rem\">Federal Grants &amp; NOFOs</h1>\n<p style=\"margin:0 0 1rem;line-height:1.7\">A federal grant is financial assistance — the government funds a project that advances a public purpose, rather than buying a product or service for its own use. That distinction matters: grants run under the Uniform Guidance (2 CFR 200), not the FAR, and they're judged on the merit and impact of your project.</p>\n<h2 style=\"font-size:1.5rem;font-weight:600;line-height:1.25;margin:1.25rem 0 .5rem\">The NOFO</h2>\n<p style=\"margin:0 0 1rem;line-height:1.7\">Opportunities are published as a Notice of Funding Opportunity (NOFO) — you'll also see the older terms FOA (Funding Opportunity Announcement) and NOFA. A NOFO tells you:</p>\n<ul style=\"list-style:disc;padding-left:1.5rem;margin:0 0 1rem\"><li style=\"margin:.25rem 0\">Who's eligible (small businesses, universities, nonprofits, states — it varies by program).</li><li style=\"margin:.25rem 0\">How much funding is available and typical award sizes.</li><li style=\"margin:.25rem 0\">What the review criteria are — the exact factors reviewers score.</li><li style=\"margin:.25rem 0\">Cost sharing / matching requirements, if any.</li><li style=\"margin:.25rem 0\">Deadlines and how to submit.</li></ul>\n<p style=\"margin:0 0 1rem;line-height:1.7\">Most NOFOs are posted on Grants.gov, the government-wide portal.</p>\n<h2 style=\"font-size:1.5rem;font-weight:600;line-height:1.25;margin:1.25rem 0 .5rem\">Grant vs cooperative agreement</h2>\n<p style=\"margin:0 0 1rem;line-height:1.7\">Both are assistance. The difference is federal involvement: a grant is mostly hands-off; a cooperative agreement means the agency is substantially involved (joint milestones, oversight). The NOFO says which it is.</p>\n<h2 style=\"font-size:1.5rem;font-weight:600;line-height:1.25;margin:1.25rem 0 .5rem\">The application</h2>\n<p style=\"margin:0 0 1rem;line-height:1.7\">Grant applications use the SF-424 family of forms plus a project narrative:</p>\n<ul style=\"list-style:disc;padding-left:1.5rem;margin:0 0 1rem\"><li style=\"margin:.25rem 0\">SF-424 — the application cover form.</li><li style=\"margin:.25rem 0\">SF-424A / SF-424C — the budget (non-construction / construction).</li><li style=\"margin:.25rem 0\">Project narrative — your plan, written to the review criteria.</li><li style=\"margin:.25rem 0\">Budget narrative — justifying every line of the SF-424A.</li><li style=\"margin:.25rem 0\">Plus attachments the NOFO requires (bio-sketches, letters, data-management plan, etc.).</li></ul>\n<h2 style=\"font-size:1.5rem;font-weight:600;line-height:1.25;margin:1.25rem 0 .5rem\">How to apply</h2>\n<ol style=\"list-style:decimal;padding-left:1.5rem;margin:0 0 1rem\"><li style=\"margin:.25rem 0\">Register first. You need a UEI (SAM.gov) and a Grants.gov account. Start early — registration takes time.</li><li style=\"margin:.25rem 0\">Read the NOFO twice. Confirm eligibility and map your project to every review criterion.</li><li style=\"margin:.25rem 0\">Build the budget. SF-424A line items with a narrative that justifies each cost.</li><li style=\"margin:.25rem 0\">Write to the criteria. Reviewers score against the stated factors — answer them in order.</li><li style=\"margin:.25rem 0\">Submit on Grants.gov before the deadline (there are no late exceptions).</li></ol>\n<h2 style=\"font-size:1.5rem;font-weight:600;line-height:1.25;margin:1.25rem 0 .5rem\">Which agencies</h2>\n<p style=\"margin:0 0 1rem;line-height:1.7\">NSF, NIH, the Department of Energy, USDA, the Department of Education, and many others run grant programs — including the grant-based side of SBIR/STTR at NSF, NIH, and DOE.</p>\n<h2 style=\"font-size:1.5rem;font-weight:600;line-height:1.25;margin:1.25rem 0 .5rem\">How this platform helps</h2>\n<p style=\"margin:0 0 1rem;line-height:1.7\">When a NOFO is curated onto your cards, the compliance side captures its review criteria and required forms, and the cost volume renders as the SF-424A the grant requires. The Studio drafts the project narrative to the review criteria, section by section, and readiness rolls up the computed budget and required attachments before you submit.</p>", "title": "Federal Grants & NOFOs: A First-Timer’s Guide", "excerpt": "Grants are assistance, not procurement. Here is how a NOFO works, the SF-424 forms, and how to apply on Grants.gov.", "section": "body", "metadata": {}}]$g168$::jsonb, $g168${"tags": ["grants", "NOFO", "Grants.gov", "getting-started"], "author": null, "canvas": {"nodes": [], "canvas": {"width": 612, "footer": null, "format": "custom", "header": null, "height": 792, "margins": {"top": 72, "left": 72, "right": 72, "bottom": 72}, "max_pages": null, "max_slides": null, "font_default": {"size": 12, "family": "Times New Roman"}, "line_spacing": 1.15}, "version": 2, "metadata": {"title": "Federal Grants & NOFOs: A First-Timer’s Guide", "status": "in_progress", "volume_id": "", "created_at": "", "proposal_id": "", "version_number": 1, "solicitation_id": "", "last_modified_at": "", "last_modified_by": "", "required_item_id": ""}, "sections": [{"id": "1078e1a3-994b-40cf-b2fc-3fe1da1f94f7", "title": "Federal Grants & NOFOs: A First-Timer’s Guide", "groups": [{"id": "52e4ad23-8098-47a2-90db-7b1c9f97a936", "nodes": [{"id": "788afd7a-1dd0-4ab5-8e43-b17a462882d4", "type": "heading", "style": {}, "content": {"text": "Federal Grants & NOFOs", "level": 1}, "history": [], "provenance": {"source": "template"}, "library_eligible": false}, {"id": "22ca5eb9-b45e-4d7d-8e18-ed4069f97043", "type": "text_block", "style": {}, "content": {"text": "A federal grant is financial assistance — the government funds a project that advances a public purpose, rather than buying a product or service for its own use. That distinction matters: grants run under the Uniform Guidance (2 CFR 200), not the FAR, and they're judged on the merit and impact of your project."}, "history": [], "provenance": {"source": "template"}, "library_eligible": false}, {"id": "2653ac6a-9b21-4e39-8a38-6fa698b1d52a", "type": "heading", "style": {}, "content": {"text": "The NOFO", "level": 2}, "history": [], "provenance": {"source": "template"}, "library_eligible": false}, {"id": "5e2583c8-96bc-4abf-aecf-4efc02dabc8d", "type": "text_block", "style": {}, "content": {"text": "Opportunities are published as a Notice of Funding Opportunity (NOFO) — you'll also see the older terms FOA (Funding Opportunity Announcement) and NOFA. A NOFO tells you:"}, "history": [], "provenance": {"source": "template"}, "library_eligible": false}, {"id": "ad7a94cc-92bb-4ba2-8ff4-3c35bcd55416", "type": "bulleted_list", "style": {}, "content": {"items": [{"text": "Who's eligible (small businesses, universities, nonprofits, states — it varies by program)."}, {"text": "How much funding is available and typical award sizes."}, {"text": "What the review criteria are — the exact factors reviewers score."}, {"text": "Cost sharing / matching requirements, if any."}, {"text": "Deadlines and how to submit."}]}, "history": [], "provenance": {"source": "template"}, "library_eligible": false}, {"id": "3f581090-0157-4482-adcc-fa8604de1d4f", "type": "text_block", "style": {}, "content": {"text": "Most NOFOs are posted on Grants.gov, the government-wide portal."}, "history": [], "provenance": {"source": "template"}, "library_eligible": false}, {"id": "551badef-f99f-4b03-a7d6-bc929b125866", "type": "heading", "style": {}, "content": {"text": "Grant vs cooperative agreement", "level": 2}, "history": [], "provenance": {"source": "template"}, "library_eligible": false}, {"id": "1d0cdb37-5c32-48d6-b727-cd281a81e91a", "type": "text_block", "style": {}, "content": {"text": "Both are assistance. The difference is federal involvement: a grant is mostly hands-off; a cooperative agreement means the agency is substantially involved (joint milestones, oversight). The NOFO says which it is."}, "history": [], "provenance": {"source": "template"}, "library_eligible": false}, {"id": "c26c8265-6806-44ad-9500-0f1e2adb37d8", "type": "heading", "style": {}, "content": {"text": "The application", "level": 2}, "history": [], "provenance": {"source": "template"}, "library_eligible": false}, {"id": "b1a88c8b-5664-4cd3-9e16-5ad3c07f52a9", "type": "text_block", "style": {}, "content": {"text": "Grant applications use the SF-424 family of forms plus a project narrative:"}, "history": [], "provenance": {"source": "template"}, "library_eligible": false}, {"id": "1eb42436-4fd8-464b-aba6-9627aa1293c2", "type": "bulleted_list", "style": {}, "content": {"items": [{"text": "SF-424 — the application cover form."}, {"text": "SF-424A / SF-424C — the budget (non-construction / construction)."}, {"text": "Project narrative — your plan, written to the review criteria."}, {"text": "Budget narrative — justifying every line of the SF-424A."}, {"text": "Plus attachments the NOFO requires (bio-sketches, letters, data-management plan, etc.)."}]}, "history": [], "provenance": {"source": "template"}, "library_eligible": false}, {"id": "8de982bb-35c4-49db-b7c4-4c07296eb57a", "type": "heading", "style": {}, "content": {"text": "How to apply", "level": 2}, "history": [], "provenance": {"source": "template"}, "library_eligible": false}, {"id": "52c9dfe5-b40c-464e-907b-9138d023718d", "type": "numbered_list", "style": {}, "content": {"items": [{"text": "Register first. You need a UEI (SAM.gov) and a Grants.gov account. Start early — registration takes time."}, {"text": "Read the NOFO twice. Confirm eligibility and map your project to every review criterion."}, {"text": "Build the budget. SF-424A line items with a narrative that justifies each cost."}, {"text": "Write to the criteria. Reviewers score against the stated factors — answer them in order."}, {"text": "Submit on Grants.gov before the deadline (there are no late exceptions)."}]}, "history": [], "provenance": {"source": "template"}, "library_eligible": false}, {"id": "7541f7e2-a3ed-47c1-942e-90aaad5fa006", "type": "heading", "style": {}, "content": {"text": "Which agencies", "level": 2}, "history": [], "provenance": {"source": "template"}, "library_eligible": false}, {"id": "a27886fd-e489-41c7-a321-0bf1eb0fccb3", "type": "text_block", "style": {}, "content": {"text": "NSF, NIH, the Department of Energy, USDA, the Department of Education, and many others run grant programs — including the grant-based side of SBIR/STTR at NSF, NIH, and DOE."}, "history": [], "provenance": {"source": "template"}, "library_eligible": false}, {"id": "8b8c47af-a8c6-4b6e-a47b-e7d11f3da23c", "type": "heading", "style": {}, "content": {"text": "How this platform helps", "level": 2}, "history": [], "provenance": {"source": "template"}, "library_eligible": false}, {"id": "0a5a368e-c9eb-43bd-b98d-119312745134", "type": "text_block", "style": {}, "content": {"text": "When a NOFO is curated onto your cards, the compliance side captures its review criteria and required forms, and the cost volume renders as the SF-424A the grant requires. The Studio drafts the project narrative to the review criteria, section by section, and readiness rolls up the computed budget and required attachments before you submit."}, "history": [], "provenance": {"source": "template"}, "library_eligible": false}]}], "layout": {"mode": "flow"}}], "document_id": "930c7866-20d9-4c8b-8067-20250e89da35"}, "excerpt": "Grants are assistance, not procurement. Here is how a NOFO works, the SF-424 forms, and how to apply on Grants.gov.", "externalUrl": null, "featuredImage": null}$g168$::jsonb, 'Drafted program primer — queued for review (#168)', 'eric@rfppipeline.com', now())
