INSERT INTO content_pages (id, page_key, content_type, version_no, status, title, blocks, metadata, audit_note, created_by, created_at)
VALUES ('64b164c4-2f7f-41bf-beaf-af2b6a6449a4', 'what-is-a-baa', 'guide', 1, 'draft', 'What Is a BAA? Broad Agency Announcements in 5 Minutes', $g168$[{"body": "<h1 style=\"font-size:1.875rem;font-weight:700;line-height:1.2;margin:1.5rem 0 .75rem\">What Is a BAA?</h1>\n<p style=\"margin:0 0 1rem;line-height:1.7\">A Broad Agency Announcement (BAA) is a competitive solicitation an agency uses to fund basic and applied research — work that advances science and technology without pointing at one specific system the government already knows it wants to buy. BAAs are authorized under FAR 6.102(d)(2) and 35.016, and evaluated through scientific/peer review rather than a lowest-price bid.</p>\n<h2 style=\"font-size:1.5rem;font-weight:600;line-height:1.25;margin:1.25rem 0 .5rem\">How a BAA differs from an SBIR/STTR topic</h2>\n<ul style=\"list-style:disc;padding-left:1.5rem;margin:0 0 1rem\"><li style=\"margin:.25rem 0\">Open-ended, not topic-locked. An SBIR topic asks for a specific innovation on a fixed cycle. A BAA states a broad research interest and invites your idea against it.</li><li style=\"margin:.25rem 0\">Rolling windows. Many BAAs stay open for a year or more with periodic submission dates, not a single close date.</li><li style=\"margin:.25rem 0\">Any organization. BAAs are generally not small-business-set-aside — universities, large primes, and small businesses all compete (though some have small-business tracks).</li><li style=\"margin:.25rem 0\">Two-step submission. Most agencies want a short white paper first; if it's encouraged, you're invited to submit a full proposal.</li></ul>\n<h2 style=\"font-size:1.5rem;font-weight:600;line-height:1.25;margin:1.25rem 0 .5rem\">Who uses them</h2>\n<p style=\"margin:0 0 1rem;line-height:1.7\">DARPA, the Office of Naval Research (ONR), the Air Force Research Laboratory (AFRL), the Army Research Office (ARO), and many science agencies run standing BAAs. DARPA's program-specific BAAs are the best-known example.</p>\n<h2 style=\"font-size:1.5rem;font-weight:600;line-height:1.25;margin:1.25rem 0 .5rem\">How to respond</h2>\n<ol style=\"list-style:decimal;padding-left:1.5rem;margin:0 0 1rem\"><li style=\"margin:.25rem 0\">Read the research areas. Map your capability to a named thrust or program manager's interest.</li><li style=\"margin:.25rem 0\">Send a white paper. A few pages: the idea, why it's novel, the technical approach, and rough cost. This is a go/no-go gate — treat it as your pitch.</li><li style=\"margin:.25rem 0\">Wait for encouragement. Agencies reply &quot;encouraged&quot; or &quot;not encouraged.&quot; Only invest in a full proposal if encouraged.</li><li style=\"margin:.25rem 0\">Write the full proposal. Technical volume + cost volume, to the BAA's page limits and format.</li></ol>\n<h2 style=\"font-size:1.5rem;font-weight:600;line-height:1.25;margin:1.25rem 0 .5rem\">How this platform helps</h2>\n<p style=\"margin:0 0 1rem;line-height:1.7\">When a BAA is curated onto your opportunity cards, the compliance side captures its page limits, format, and evaluation factors, and the Proposal Studio drafts the technical and cost volumes against them — white-paper first, full proposal on encouragement. The cost volume renders in the form the agency requires.</p>", "title": "What Is a BAA? Broad Agency Announcements in 5 Minutes", "excerpt": "How Broad Agency Announcements fund basic and applied research — and how to respond to one.", "section": "body", "metadata": {}}]$g168$::jsonb, $g168${"tags": ["BAA", "research", "DARPA", "getting-started"], "author": null, "canvas": {"nodes": [], "canvas": {"width": 612, "footer": null, "format": "custom", "header": null, "height": 792, "margins": {"top": 72, "left": 72, "right": 72, "bottom": 72}, "max_pages": null, "max_slides": null, "font_default": {"size": 12, "family": "Times New Roman"}, "line_spacing": 1.15}, "version": 2, "metadata": {"title": "What Is a BAA? Broad Agency Announcements in 5 Minutes", "status": "in_progress", "volume_id": "", "created_at": "", "proposal_id": "", "version_number": 1, "solicitation_id": "", "last_modified_at": "", "last_modified_by": "", "required_item_id": ""}, "sections": [{"id": "28b14d92-f20e-4d9a-91b1-241565137456", "title": "What Is a BAA? Broad Agency Announcements in 5 Minutes", "groups": [{"id": "2fede42e-80bd-4055-93b3-001cfa9e911a", "nodes": [{"id": "c10fdde0-7241-4c4f-8529-f78387872547", "type": "heading", "style": {}, "content": {"text": "What Is a BAA?", "level": 1}, "history": [], "provenance": {"source": "template"}, "library_eligible": false}, {"id": "35387f57-bbcc-4717-8c6d-fa7338361fb5", "type": "text_block", "style": {}, "content": {"text": "A Broad Agency Announcement (BAA) is a competitive solicitation an agency uses to fund basic and applied research — work that advances science and technology without pointing at one specific system the government already knows it wants to buy. BAAs are authorized under FAR 6.102(d)(2) and 35.016, and evaluated through scientific/peer review rather than a lowest-price bid."}, "history": [], "provenance": {"source": "template"}, "library_eligible": false}, {"id": "f0e9508b-fa76-4f0d-966e-2529ea062d53", "type": "heading", "style": {}, "content": {"text": "How a BAA differs from an SBIR/STTR topic", "level": 2}, "history": [], "provenance": {"source": "template"}, "library_eligible": false}, {"id": "680c5b12-c3dc-4142-b8d5-380ecf44dddd", "type": "bulleted_list", "style": {}, "content": {"items": [{"text": "Open-ended, not topic-locked. An SBIR topic asks for a specific innovation on a fixed cycle. A BAA states a broad research interest and invites your idea against it."}, {"text": "Rolling windows. Many BAAs stay open for a year or more with periodic submission dates, not a single close date."}, {"text": "Any organization. BAAs are generally not small-business-set-aside — universities, large primes, and small businesses all compete (though some have small-business tracks)."}, {"text": "Two-step submission. Most agencies want a short white paper first; if it's encouraged, you're invited to submit a full proposal."}]}, "history": [], "provenance": {"source": "template"}, "library_eligible": false}, {"id": "f3c162b0-474c-4599-9bee-7cacb4957643", "type": "heading", "style": {}, "content": {"text": "Who uses them", "level": 2}, "history": [], "provenance": {"source": "template"}, "library_eligible": false}, {"id": "4cc14852-a2af-401f-9e90-ba84226ec373", "type": "text_block", "style": {}, "content": {"text": "DARPA, the Office of Naval Research (ONR), the Air Force Research Laboratory (AFRL), the Army Research Office (ARO), and many science agencies run standing BAAs. DARPA's program-specific BAAs are the best-known example."}, "history": [], "provenance": {"source": "template"}, "library_eligible": false}, {"id": "bcaf065b-f7e7-49bb-8ef5-242928e65df4", "type": "heading", "style": {}, "content": {"text": "How to respond", "level": 2}, "history": [], "provenance": {"source": "template"}, "library_eligible": false}, {"id": "de04b23b-0780-4b27-856d-caa576dc977a", "type": "numbered_list", "style": {}, "content": {"items": [{"text": "Read the research areas. Map your capability to a named thrust or program manager's interest."}, {"text": "Send a white paper. A few pages: the idea, why it's novel, the technical approach, and rough cost. This is a go/no-go gate — treat it as your pitch."}, {"text": "Wait for encouragement. Agencies reply \"encouraged\" or \"not encouraged.\" Only invest in a full proposal if encouraged."}, {"text": "Write the full proposal. Technical volume + cost volume, to the BAA's page limits and format."}]}, "history": [], "provenance": {"source": "template"}, "library_eligible": false}, {"id": "e57ebffa-4bf7-4630-be5f-baeae70e08f7", "type": "heading", "style": {}, "content": {"text": "How this platform helps", "level": 2}, "history": [], "provenance": {"source": "template"}, "library_eligible": false}, {"id": "b155c013-841f-4e21-afb9-254d1f490885", "type": "text_block", "style": {}, "content": {"text": "When a BAA is curated onto your opportunity cards, the compliance side captures its page limits, format, and evaluation factors, and the Proposal Studio drafts the technical and cost volumes against them — white-paper first, full proposal on encouragement. The cost volume renders in the form the agency requires."}, "history": [], "provenance": {"source": "template"}, "library_eligible": false}]}], "layout": {"mode": "flow"}}], "document_id": "9f6494fd-3a25-484a-820a-59415c5049a0"}, "excerpt": "How Broad Agency Announcements fund basic and applied research — and how to respond to one.", "externalUrl": null, "featuredImage": null}$g168$::jsonb, 'Drafted program primer — queued for review (#168)', 'eric@rfppipeline.com', now())
ON CONFLICT (id) DO NOTHING;

INSERT INTO content_pages (id, page_key, content_type, version_no, status, title, blocks, metadata, audit_note, created_by, created_at)
VALUES ('b282a751-0fc8-4641-ac12-8c3fb1c32732', 'what-is-a-cso', 'guide', 1, 'draft', 'What Is a CSO? Commercial Solutions Openings, Explained', $g168$[{"body": "<h1 style=\"font-size:1.875rem;font-weight:700;line-height:1.2;margin:1.5rem 0 .75rem\">What Is a CSO?</h1>\n<p style=\"margin:0 0 1rem;line-height:1.7\">A Commercial Solutions Opening (CSO) is a competitive procedure the government uses to acquire innovative commercial products and services that close a capability gap. Made a permanent authority in the FY22 NDAA (10 U.S.C. § 3458), a CSO is solutions-based: the government publishes a problem or area of interest, and companies pitch how they'd solve it — rather than responding to a rigid specification.</p>\n<h2 style=\"font-size:1.5rem;font-weight:600;line-height:1.25;margin:1.25rem 0 .5rem\">What makes a CSO different</h2>\n<ul style=\"list-style:disc;padding-left:1.5rem;margin:0 0 1rem\"><li style=\"margin:.25rem 0\">Problem, not spec. The solicitation describes an outcome or capability gap. You propose the solution.</li><li style=\"margin:.25rem 0\">Commercial-first. CSOs target commercial or dual-use technology that already exists or is close to market — not ground-up development.</li><li style=\"margin:.25rem 0\">Pitch-driven. Most CSOs start with a short white paper or pitch; promising ideas are invited to a full proposal or an oral pitch.</li><li style=\"margin:.25rem 0\">Flexible award. A CSO can lead to a FAR contract or an Other Transaction, and awards are made on merit — there's no requirement to pick the lowest price.</li></ul>\n<h2 style=\"font-size:1.5rem;font-weight:600;line-height:1.25;margin:1.25rem 0 .5rem\">Who uses them</h2>\n<p style=\"margin:0 0 1rem;line-height:1.7\">The Defense Innovation Unit (DIU) pioneered the CSO-style &quot;commercial solutions&quot; process, and military services and agencies now run their own CSOs to reach commercial vendors quickly.</p>\n<h2 style=\"font-size:1.5rem;font-weight:600;line-height:1.25;margin:1.25rem 0 .5rem\">How to respond</h2>\n<ol style=\"list-style:decimal;padding-left:1.5rem;margin:0 0 1rem\"><li style=\"margin:.25rem 0\">Match the problem statement. Show that your commercial capability maps to the stated gap.</li><li style=\"margin:.25rem 0\">Submit a concise pitch/white paper. Lead with the outcome and the evidence it works (customers, TRL, results).</li><li style=\"margin:.25rem 0\">Prepare for an oral pitch. Many CSOs invite finalists to present.</li><li style=\"margin:.25rem 0\">Negotiate the award — contract or OT — on scope, price, and delivery.</li></ol>\n<h2 style=\"font-size:1.5rem;font-weight:600;line-height:1.25;margin:1.25rem 0 .5rem\">CSO vs BAA vs OTA</h2>\n<ul style=\"list-style:disc;padding-left:1.5rem;margin:0 0 1rem\"><li style=\"margin:.25rem 0\">A BAA funds research (advancing the science). A CSO buys commercial solutions (fielding what largely exists).</li><li style=\"margin:.25rem 0\">A CSO is a procedure for selecting a solution; an OTA can be the instrument that funds it. They're often used together.</li></ul>\n<h2 style=\"font-size:1.5rem;font-weight:600;line-height:1.25;margin:1.25rem 0 .5rem\">How this platform helps</h2>\n<p style=\"margin:0 0 1rem;line-height:1.7\">A CSO rewards a crisp, evidence-backed pitch. When one is curated onto your cards, the Studio drafts the white paper and pitch narrative around your capability statement and past performance, and the compliance side tracks the submission format and evaluation factors so nothing is missed before you submit.</p>", "title": "What Is a CSO? Commercial Solutions Openings, Explained", "excerpt": "A Commercial Solutions Opening buys innovative commercial technology through a pitch-first, solutions-based process.", "section": "body", "metadata": {}}]$g168$::jsonb, $g168${"tags": ["CSO", "commercial", "innovation", "getting-started"], "author": null, "canvas": {"nodes": [], "canvas": {"width": 612, "footer": null, "format": "custom", "header": null, "height": 792, "margins": {"top": 72, "left": 72, "right": 72, "bottom": 72}, "max_pages": null, "max_slides": null, "font_default": {"size": 12, "family": "Times New Roman"}, "line_spacing": 1.15}, "version": 2, "metadata": {"title": "What Is a CSO? Commercial Solutions Openings, Explained", "status": "in_progress", "volume_id": "", "created_at": "", "proposal_id": "", "version_number": 1, "solicitation_id": "", "last_modified_at": "", "last_modified_by": "", "required_item_id": ""}, "sections": [{"id": "fbbf8053-2b96-4fc6-b6c9-e8df1ccd80af", "title": "What Is a CSO? Commercial Solutions Openings, Explained", "groups": [{"id": "526446bf-0983-4227-89b6-d3c832e7f610", "nodes": [{"id": "b2cf0130-0c35-4cec-8606-04874f029cdd", "type": "heading", "style": {}, "content": {"text": "What Is a CSO?", "level": 1}, "history": [], "provenance": {"source": "template"}, "library_eligible": false}, {"id": "0942ccf4-6c88-454b-9fef-2bec005c2844", "type": "text_block", "style": {}, "content": {"text": "A Commercial Solutions Opening (CSO) is a competitive procedure the government uses to acquire innovative commercial products and services that close a capability gap. Made a permanent authority in the FY22 NDAA (10 U.S.C. § 3458), a CSO is solutions-based: the government publishes a problem or area of interest, and companies pitch how they'd solve it — rather than responding to a rigid specification."}, "history": [], "provenance": {"source": "template"}, "library_eligible": false}, {"id": "a23c4049-f1c4-4c78-83b5-69a980151c8b", "type": "heading", "style": {}, "content": {"text": "What makes a CSO different", "level": 2}, "history": [], "provenance": {"source": "template"}, "library_eligible": false}, {"id": "02307bb2-97b1-4aa1-8b60-8e593185107d", "type": "bulleted_list", "style": {}, "content": {"items": [{"text": "Problem, not spec. The solicitation describes an outcome or capability gap. You propose the solution."}, {"text": "Commercial-first. CSOs target commercial or dual-use technology that already exists or is close to market — not ground-up development."}, {"text": "Pitch-driven. Most CSOs start with a short white paper or pitch; promising ideas are invited to a full proposal or an oral pitch."}, {"text": "Flexible award. A CSO can lead to a FAR contract or an Other Transaction, and awards are made on merit — there's no requirement to pick the lowest price."}]}, "history": [], "provenance": {"source": "template"}, "library_eligible": false}, {"id": "83d562e7-c949-4c71-ae39-e3ebe86519b7", "type": "heading", "style": {}, "content": {"text": "Who uses them", "level": 2}, "history": [], "provenance": {"source": "template"}, "library_eligible": false}, {"id": "46c489a4-8856-4b99-9fea-8de631ee94a0", "type": "text_block", "style": {}, "content": {"text": "The Defense Innovation Unit (DIU) pioneered the CSO-style \"commercial solutions\" process, and military services and agencies now run their own CSOs to reach commercial vendors quickly."}, "history": [], "provenance": {"source": "template"}, "library_eligible": false}, {"id": "a2bddc04-bb85-4424-904b-ffadfffc5c91", "type": "heading", "style": {}, "content": {"text": "How to respond", "level": 2}, "history": [], "provenance": {"source": "template"}, "library_eligible": false}, {"id": "cfeb4905-026e-4426-8955-36f23423679f", "type": "numbered_list", "style": {}, "content": {"items": [{"text": "Match the problem statement. Show that your commercial capability maps to the stated gap."}, {"text": "Submit a concise pitch/white paper. Lead with the outcome and the evidence it works (customers, TRL, results)."}, {"text": "Prepare for an oral pitch. Many CSOs invite finalists to present."}, {"text": "Negotiate the award — contract or OT — on scope, price, and delivery."}]}, "history": [], "provenance": {"source": "template"}, "library_eligible": false}, {"id": "f1116f2b-2e6d-40c3-be71-ad6d2af72330", "type": "heading", "style": {}, "content": {"text": "CSO vs BAA vs OTA", "level": 2}, "history": [], "provenance": {"source": "template"}, "library_eligible": false}, {"id": "c36dac5c-1684-4765-9456-08a895b6a262", "type": "bulleted_list", "style": {}, "content": {"items": [{"text": "A BAA funds research (advancing the science). A CSO buys commercial solutions (fielding what largely exists)."}, {"text": "A CSO is a procedure for selecting a solution; an OTA can be the instrument that funds it. They're often used together."}]}, "history": [], "provenance": {"source": "template"}, "library_eligible": false}, {"id": "23d1f655-6451-4ead-85e2-1ff55650893d", "type": "heading", "style": {}, "content": {"text": "How this platform helps", "level": 2}, "history": [], "provenance": {"source": "template"}, "library_eligible": false}, {"id": "675b8cac-1e8f-4c83-952b-3931a06dbf27", "type": "text_block", "style": {}, "content": {"text": "A CSO rewards a crisp, evidence-backed pitch. When one is curated onto your cards, the Studio drafts the white paper and pitch narrative around your capability statement and past performance, and the compliance side tracks the submission format and evaluation factors so nothing is missed before you submit."}, "history": [], "provenance": {"source": "template"}, "library_eligible": false}]}], "layout": {"mode": "flow"}}], "document_id": "4d85b8e4-2021-4dde-a91b-6bd7e2d724eb"}, "excerpt": "A Commercial Solutions Opening buys innovative commercial technology through a pitch-first, solutions-based process.", "externalUrl": null, "featuredImage": null}$g168$::jsonb, 'Drafted program primer — queued for review (#168)', 'eric@rfppipeline.com', now())
ON CONFLICT (id) DO NOTHING;

INSERT INTO content_pages (id, page_key, content_type, version_no, status, title, blocks, metadata, audit_note, created_by, created_at)
VALUES ('eafc9e07-a446-4ce5-84a8-a54f40efc4ba', 'what-is-an-ota', 'guide', 1, 'draft', 'What Is an OTA? Other Transaction Agreements Explained', $g168$[{"body": "<h1 style=\"font-size:1.875rem;font-weight:700;line-height:1.2;margin:1.5rem 0 .75rem\">What Is an OTA?</h1>\n<p style=\"margin:0 0 1rem;line-height:1.7\">An Other Transaction (OT) agreement is a funding instrument the Department of Defense (and a few civilian agencies) uses outside the Federal Acquisition Regulation. Congress created OT authority to let the government work with innovators — especially nontraditional defense contractors — without the full weight of FAR-based contracting. The core authorities are 10 U.S.C. § 4021 (research) and § 4022 (prototype projects), with a path to follow-on production under § 4023.</p>\n<h2 style=\"font-size:1.5rem;font-weight:600;line-height:1.25;margin:1.25rem 0 .5rem\">Why OTs exist</h2>\n<p style=\"margin:0 0 1rem;line-height:1.7\">Standard FAR contracts carry cost-accounting, IP, and compliance requirements that many commercial and early-stage companies can't (or won't) take on. OTs are negotiated agreements — terms, IP, and milestones are tailored to the project — which lowers the barrier for firms that have never sold to the government.</p>\n<h2 style=\"font-size:1.5rem;font-weight:600;line-height:1.25;margin:1.25rem 0 .5rem\">The three flavors</h2>\n<ul style=\"list-style:disc;padding-left:1.5rem;margin:0 0 1rem\"><li style=\"margin:.25rem 0\">Research OT (§ 4021) — basic/applied research, often cost-shared.</li><li style=\"margin:.25rem 0\">Prototype OT (§ 4022) — build and demonstrate a prototype that addresses a defense need. The most common entry point.</li><li style=\"margin:.25rem 0\">Follow-on Production OT (§ 4023) — a successful prototype can transition to production without a new competition. This is the prize: prototype well, and production can follow.</li></ul>\n<h2 style=\"font-size:1.5rem;font-weight:600;line-height:1.25;margin:1.25rem 0 .5rem\">Consortia — the usual front door</h2>\n<p style=\"margin:0 0 1rem;line-height:1.7\">Many prototype OTs are awarded through consortia managed by a Consortium Management Firm: NSTXL, MTEC, C5, SOSSEC, and others, plus the Defense Innovation Unit (DIU). You join the consortium (often free or low-cost), then respond to request-for-solutions/prototype-project announcements with a short solution brief and, if selected, a proposal.</p>\n<h2 style=\"font-size:1.5rem;font-weight:600;line-height:1.25;margin:1.25rem 0 .5rem\">How to respond</h2>\n<ol style=\"list-style:decimal;padding-left:1.5rem;margin:0 0 1rem\"><li style=\"margin:.25rem 0\">Find the consortium that fields your technology area and become a member.</li><li style=\"margin:.25rem 0\">Watch for solution calls. They read like a problem statement, not a spec.</li><li style=\"margin:.25rem 0\">Submit a solution brief — concise, outcome-focused, milestone-driven.</li><li style=\"margin:.25rem 0\">Negotiate the agreement if selected: scope, milestones, payments, and IP.</li></ol>\n<h2 style=\"font-size:1.5rem;font-weight:600;line-height:1.25;margin:1.25rem 0 .5rem\">How this platform helps</h2>\n<p style=\"margin:0 0 1rem;line-height:1.7\">OT solicitations don't look like RFPs — they're problem statements with milestone-based deliverables. When one is curated onto your cards, the compliance side captures the milestone structure and the Studio drafts a solution brief and a milestone/payment plan against it, with the cost volume computed in the required form.</p>", "title": "What Is an OTA? Other Transaction Agreements Explained", "excerpt": "Other Transactions fund prototypes and research outside the FAR — often through consortia. Here is how they work.", "section": "body", "metadata": {}}]$g168$::jsonb, $g168${"tags": ["OTA", "prototype", "consortium", "getting-started"], "author": null, "canvas": {"nodes": [], "canvas": {"width": 612, "footer": null, "format": "custom", "header": null, "height": 792, "margins": {"top": 72, "left": 72, "right": 72, "bottom": 72}, "max_pages": null, "max_slides": null, "font_default": {"size": 12, "family": "Times New Roman"}, "line_spacing": 1.15}, "version": 2, "metadata": {"title": "What Is an OTA? Other Transaction Agreements Explained", "status": "in_progress", "volume_id": "", "created_at": "", "proposal_id": "", "version_number": 1, "solicitation_id": "", "last_modified_at": "", "last_modified_by": "", "required_item_id": ""}, "sections": [{"id": "68ea9fc0-a211-4637-a36b-f6ca34e611ce", "title": "What Is an OTA? Other Transaction Agreements Explained", "groups": [{"id": "91a38310-2d94-4e3e-8986-d7bac531649a", "nodes": [{"id": "ed84bc01-4b27-4e42-9622-c8e04153496c", "type": "heading", "style": {}, "content": {"text": "What Is an OTA?", "level": 1}, "history": [], "provenance": {"source": "template"}, "library_eligible": false}, {"id": "c029e518-82af-4cec-94df-62d582a5c8b8", "type": "text_block", "style": {}, "content": {"text": "An Other Transaction (OT) agreement is a funding instrument the Department of Defense (and a few civilian agencies) uses outside the Federal Acquisition Regulation. Congress created OT authority to let the government work with innovators — especially nontraditional defense contractors — without the full weight of FAR-based contracting. The core authorities are 10 U.S.C. § 4021 (research) and § 4022 (prototype projects), with a path to follow-on production under § 4023."}, "history": [], "provenance": {"source": "template"}, "library_eligible": false}, {"id": "4778a6ea-5ec2-4c99-958a-fd9404f62f9a", "type": "heading", "style": {}, "content": {"text": "Why OTs exist", "level": 2}, "history": [], "provenance": {"source": "template"}, "library_eligible": false}, {"id": "2f78ca1c-47c3-44e5-827f-730fb7da030e", "type": "text_block", "style": {}, "content": {"text": "Standard FAR contracts carry cost-accounting, IP, and compliance requirements that many commercial and early-stage companies can't (or won't) take on. OTs are negotiated agreements — terms, IP, and milestones are tailored to the project — which lowers the barrier for firms that have never sold to the government."}, "history": [], "provenance": {"source": "template"}, "library_eligible": false}, {"id": "eba394b4-293f-42f9-bece-ee1c4bb0d4fa", "type": "heading", "style": {}, "content": {"text": "The three flavors", "level": 2}, "history": [], "provenance": {"source": "template"}, "library_eligible": false}, {"id": "cef91b2e-182f-4662-82af-bd4dc116c708", "type": "bulleted_list", "style": {}, "content": {"items": [{"text": "Research OT (§ 4021) — basic/applied research, often cost-shared."}, {"text": "Prototype OT (§ 4022) — build and demonstrate a prototype that addresses a defense need. The most common entry point."}, {"text": "Follow-on Production OT (§ 4023) — a successful prototype can transition to production without a new competition. This is the prize: prototype well, and production can follow."}]}, "history": [], "provenance": {"source": "template"}, "library_eligible": false}, {"id": "dde569a8-f3af-427e-8915-0ba069c9dac8", "type": "heading", "style": {}, "content": {"text": "Consortia — the usual front door", "level": 2}, "history": [], "provenance": {"source": "template"}, "library_eligible": false}, {"id": "7fe43eff-0023-4249-90ee-0fb3e85421a8", "type": "text_block", "style": {}, "content": {"text": "Many prototype OTs are awarded through consortia managed by a Consortium Management Firm: NSTXL, MTEC, C5, SOSSEC, and others, plus the Defense Innovation Unit (DIU). You join the consortium (often free or low-cost), then respond to request-for-solutions/prototype-project announcements with a short solution brief and, if selected, a proposal."}, "history": [], "provenance": {"source": "template"}, "library_eligible": false}, {"id": "610d8e9d-0dc2-4c54-ae23-94034595545a", "type": "heading", "style": {}, "content": {"text": "How to respond", "level": 2}, "history": [], "provenance": {"source": "template"}, "library_eligible": false}, {"id": "eca6f3df-ca8c-4d3a-8e65-afa08a10f129", "type": "numbered_list", "style": {}, "content": {"items": [{"text": "Find the consortium that fields your technology area and become a member."}, {"text": "Watch for solution calls. They read like a problem statement, not a spec."}, {"text": "Submit a solution brief — concise, outcome-focused, milestone-driven."}, {"text": "Negotiate the agreement if selected: scope, milestones, payments, and IP."}]}, "history": [], "provenance": {"source": "template"}, "library_eligible": false}, {"id": "019f79ed-e041-4fa8-9d3b-e4f9ce47abf8", "type": "heading", "style": {}, "content": {"text": "How this platform helps", "level": 2}, "history": [], "provenance": {"source": "template"}, "library_eligible": false}, {"id": "4e50a38d-155a-42ea-8faf-5910c824eb0e", "type": "text_block", "style": {}, "content": {"text": "OT solicitations don't look like RFPs — they're problem statements with milestone-based deliverables. When one is curated onto your cards, the compliance side captures the milestone structure and the Studio drafts a solution brief and a milestone/payment plan against it, with the cost volume computed in the required form."}, "history": [], "provenance": {"source": "template"}, "library_eligible": false}]}], "layout": {"mode": "flow"}}], "document_id": "dc459dd3-e249-4294-b322-3c1d7a3391e9"}, "excerpt": "Other Transactions fund prototypes and research outside the FAR — often through consortia. Here is how they work.", "externalUrl": null, "featuredImage": null}$g168$::jsonb, 'Drafted program primer — queued for review (#168)', 'eric@rfppipeline.com', now())
ON CONFLICT (id) DO NOTHING;

